"내 공격 턴마다, 이 유닛이 공격을 시작할 때 맞선 유닛에서 칸이 가장 먼 상대 유닛에게 함께 던져 {0} 피해를 줌(그 유닛의 방어만큼 줄어듦. 거리가 같으면 전장 번호가 큰 유닛). 상대 유닛이 맞선 유닛뿐이면 던지지 않음.": "每个我方攻击回合,此单位开始攻击时,同时向距离所对峙单位格数最远的敌方单位投掷,造成伤害{0}(按该单位的防御减少;距离相同时选战场编号较大的单位)。若敌方只有所对峙的单位则不投掷。",
