"맞붙어 피해를 주면(공격 · 반격 모두), 맞은 유닛이 쓰러지지 않았을 때 남은 체력이 1이 됨.": "交锋中造成伤害时(攻击・反击皆可),被击中的单位若未倒下,剩余体力变为1。",
