"가": "",
"가르운의 오크 족장": "加伦的兽人族长",
"강철은 물러서지 않는다": "钢铁绝不后退",
"거인 도르마크의 식지 않은 심장불이 깨운 것들 — 포르탄의 고블린 포병, 깨어난 화약, 불의 정령, 화산의 짐승. 광역 피해와 순간 화력이 강하지만, 쏜 다음 턴에는 장전해야 한다.": "巨人多尔马克永不冷却的心火所唤醒之物 — 福尔坦的哥布林炮兵、苏醒的火药、火之精灵、火山之兽。范围伤害与爆发火力强大,但开火后的下一回合必须装填。",
"거인 소르그림의 힘줄 광맥에서 캔 쇠와 그 쇠가 깨운 것들 — 두르크하임의 드워프, 골렘 · 오토마톤, 깨어난 무구, 쇠를 먹는 짐승. 장갑으로 피해를 줄이며 버티지만 느리고 저주에 약하다.": "从巨人索尔格林的筋脉矿中掘出的铁,以及被那铁唤醒之物 — 杜尔克海姆的矮人、魔像・自动人偶、苏醒的武具、食铁之兽。以装甲减伤坚守,但迟缓且惧怕诅咒。",
"거인 케라운의 번개 신경이 땅 위로 튄 것과 그것을 가둔 볼타리움의 노움 학자들 — 번개 정령, 축전 기계, 폭풍의 짐승. 충전을 쌓고 장치를 깔아 두었다가 한 번에 터뜨린다.": "巨人凯拉温的雷电神经迸出地面之物,以及将其封存的沃尔塔里姆侏儒学者 — 雷电精灵、蓄电机械、风暴之兽。积蓄充能、布设装置,再一举引爆。",
"고목뿔 용 베르단이 지키는 숲과 그 숲이 몸을 얻은 것들 — 실바니엘의 트롤, 트렌트 · 드라이어드, 버섯족, 숲의 짐승. 잘려도 다시 자라는 몸으로 가시로 피해를 돌려주고 재생하며 오래 버틴다. 불에 약하다.": "古木之角龙维尔丹守护的森林,以及那森林所化身之物 — 希尔瓦尼尔的巨魔、树人・树精、蘑菇族、森林之兽。以斩断亦能再生的身躯,用荆棘反弹伤害、再生并持久坚守。惧怕火焰。",
"공/방": "攻/防",
"공격 · 반격할 때 상대 방어를 모두 무시.": "攻击・反击时无视对方全部防御。",
"공격 당해 체력이 깎이면 상대 체력 −{0}.": "受到攻击而体力减少时,对方体力−{0}。",
"공격 차례에 체력이 가장 낮은 상대에게 체력 −{0}.": "攻击时,对体力最低的敌方造成体力−{0}。",
"공격 턴마다 가장 먼 상대 유닛에게 피해 {0}.": "每个攻击回合,对最远的敌方单位造成伤害{0}。",
"공격 턴엔 공격 +{0}, 방어 턴엔 방어 +{0}.": "攻击回合攻击+{0},防御回合防御+{0}。",
"공격받을 때 · 반격할 때만": "仅受到攻击・反击时",
"공격받을 때 방어가 막은 만큼 공격자 체력 −.": "受到攻击时,攻击者体力−防御所挡下的数值。",
"공격하면, 상대 유닛의 방어가 이번 턴 동안 내 공격력만큼 줄어든다(0까지만).": "攻击时,对方单位的防御本回合降低等同于自身攻击力的数值(最低为0)。",
"공격한 상대에 화상 {0} — 다음 턴 시작 때 체력 −{0}{1}.": "对所攻击的敌方施加灼烧{0} — 下回合开始时体力−{0}{1}。",
"공격한 상대의 방어를 내 공격력만큼 깎는다(이번 턴).": "将所攻击敌方的防御削减等同于自身攻击力的数值(本回合)。",
"공격할 때 상대 방어를 더해 깎는다(최대 {0}).": "攻击时额外加上对方的防御进行削减(最多{0})。",
"공격할 때 상대 방어를 더해서 체력을 깎는다(최대 {0}).": "攻击时额外加上对方的防御削减体力(最多{0})。",
"공격할 때도 반격할 때도": "攻击与反击时皆可",
"공격할 때만": "仅攻击时",
"공격해 맞붙은 상대 유닛이 살아남으면, 그 유닛을 바로 뒤 상대 유닛과 자리를 바꿔 밀어낸다(마법 칸은 건너뛴다). [굳건] 유닛은 밀리지 않는다. 반격할 때는 적용되지 않는다.": "交锋中攻击的敌方单位存活时,将其与身后紧邻的敌方单位交换位置推后(跳过法术格)。[坚定]单位不会被推开。反击时不适用。",
"공격해 맞붙은 상대 유닛이 살아남으면, 그 유닛을 바로 뒤 상대 유닛과 자리를 바꿔 밀어낸다(마법 칸은 건너뛴다). 다음 아군은 뒤에 있던 유닛과 맞붙는다. [굳건] 유닛은 밀리지 않는다. 반격할 때는 적용되지 않는다.": "交锋中攻击的敌方单位存活时,将其与身后紧邻的敌方单位交换位置推后(跳过法术格)。下一个友方将与原本在后的单位交锋。[坚定]单位不会被推开。反击时不适用。",
"공격해 살아남은 상대를 바로 뒤로 밀어낸다.": "将攻击后存活的敌方推至身后。",
"공격해 온 상대 체력 −1, 나는 체력 +1.": "攻击者体力−1,自身体力+1。",
