"이": "",
"이 마법을 쓰면 다음 턴 에테르가 {0} 줄어든다.": "使用此法术后,下回合以太减少{0}。",
"이 마법을 쓸 때 생명 {0}을 제물로 바친다. 이 마법이 겨눈 상대 유닛에 [제물 증표]가 붙는다(상대 유닛을 겨누지 않는 마법은 상대 맨 앞 유닛에). 증표가 붙은 유닛이 이번 전투에서 쓰러지면 바친 생명이 돌아오고, 그 유닛 카드는 내 소각장으로 간다(마법 하나에 한 번). 돌아올 제물이 있는 동안은 전투 중 생명이 0 아래로 내려가도 판이 끝나지 않는다(전투가 끝날 때도 0 아래면 패배).": "使用此法术时献祭{0}点生命。此法术瞄准的敌方单位附加[献祭印记](不瞄准敌方单位的法术则附加于敌方最前单位)。带印记的单位在本场战斗中倒下时,献祭的生命返还,该单位卡牌进入我方焚烧场(每个法术一次)。在有献祭待返还期间,即使战斗中生命低于0,对局也不会结束(战斗结束时仍低于0则失败)。",
"이 유닛을 맞붙어 공격한 상대 유닛에 [화상 {0}]을 붙인다. 화상은 붙은 그 자리에서는 피해가 없다. 여러 번 붙으면 합쳐지지 않고 하나씩 따로 남는다. 다음 턴 전투가 시작될 때 화상마다 그 수치만큼 체력이 깎인 뒤(방어 무시) 꺼진다.{1}": "对在交锋中攻击此单位的敌方单位施加[灼烧 {0}]。灼烧在施加当下不造成伤害。多次施加不会合并,各自独立保留。下回合战斗开始时,每层灼烧使体力削减等同其数值(无视防御)后消失。{1}",
"이 유닛을 맞붙어 공격한 상대 유닛은 다음 턴 공격이 {0} 줄어든다(이 유닛이 쓰러져도). 여러 번 걸려도 더해지지 않는다.": "在交锋中攻击此单位的敌方单位下回合攻击减少{0}(即使此单位倒下)。多次施加不叠加。",
"이 유닛을 맞붙어 공격한 상대 유닛의 체력이 1 깎이고, 이 유닛은 받은 피해를 1 채운다.": "在交锋中攻击此单位的敌方单位体力削减1,此单位回复1点所受伤害。",
"이 유닛이 맞붙어 공격한 상대 유닛에 [화상 {0}]을 남긴다(그 공격으로 쓰러뜨리면 남지 않음). 화상은 붙은 그 자리에서는 피해가 없다. 여러 번 붙으면 합쳐지지 않고 하나씩 따로 남는다. 다음 턴 전투가 시작될 때 화상마다 그 수치만큼 체력이 깎인 뒤(방어 무시) 꺼진다.{1}": "在此单位于交锋中攻击的敌方单位上留下[灼烧 {0}](若该次攻击将其击倒则不留下)。灼烧在施加当下不造成伤害。多次施加不会合并,各自独立保留。下回合战斗开始时,每层灼烧使体力削减等同其数值(无视防御)后消失。{1}",
"이 유닛이 상대 유닛을 쓰러뜨리면(공격 · 반격 · 사격 · 투척. 연쇄 · 꿰뚫기로 뒤 유닛을 쓰러뜨린 것은 세지 않음) 내 다음 턴 에테르가 쓰러뜨린 유닛 레벨의 절반(올림)만큼 늘어난다.": "此单位击倒敌方单位时(攻击・反击・射击・投掷;以连锁・贯穿击倒后方单位的不计),我方下回合以太增加被击倒单位等级的一半(向上取整)。",
"이 유닛이 전장에 있으면 내 마법(공격 · 공용 · 방어)이 상대 유닛에게 주는 피해가 맞는 유닛마다 {0} 늘어난다. 늘어난 몫은 물리 피해 — 먼저 그 유닛의 방어를 이번 턴 그만큼 깎고, 방어를 넘긴 만큼만 체력에 들어간다.": "此单位在战场上时,我方法术(攻击・通用・防御)对敌方单位造成的伤害,每个被击中的单位增加{0}。增加部分为物理伤害 — 先使该单位本回合防御降低相同数值,仅超出防御的部分计入体力。",
"이 유닛이 피해를 준 상대 유닛(맞붙음 · 사격)은 이번 턴 방어가 2 줄어든다(유닛마다 턴에 한 번).": "被此单位造成伤害的敌方单位(交锋・射击)本回合防御降低2(每个单位每回合一次)。",
"이번 턴 내 마법에 맞은 상대 유닛과 맞붙으면(공격 · 반격) 피해가 2 늘어난다. 마법이 피해를 겨눈 유닛이면 보호막 · 가호에 막혔어도 맞은 것으로 친다.": "本回合与被我方法术命中的敌方单位交锋时(攻击・反击),伤害增加2。被伤害法术瞄准的单位即使被护盾・庇佑挡下也视为命中。",
"이번 턴 동안 방어가 마법·코인으로 깎이지 않고(올리는 것은 그대로 붙음), 이미 깎인 방어는 원래 값으로 돌아온다. 피해는 그대로 받는다. [저주]([공포] · [역병] · [빙의] · [정신 지배])도 걸리지 않고, 걸려 있던 저주는 사라진다.": "本回合防御不会被法术・硬币削减(提升效果照常),已被削减的防御恢复原值。伤害照常承受。也不会中[诅咒]([恐惧]・[瘟疫]・[附身]・[精神控制]),已中的诅咒消失。",
"이번 턴, 맞붙어 공격하면 맞선 유닛 바로 뒤의 상대 유닛도 같은 공격을 받는다(그 유닛의 방어를 뺀 피해, 반격은 없음).": "本回合交锋攻击时,所对峙单位身后紧邻的敌方单位也受到同样的攻击(伤害扣除该单位的防御,无反击)。",
"이번 턴, 쓰러질 만큼의 피해를 처음 받으면 쓰러지지 않고 체력 1로 버틴다(한 번). 파괴 · 코인에는 통하지 않는다.": "本回合首次受到致命伤害时不会倒下,以1点体力坚持(一次)。对摧毁・硬币无效。",
"잊지 않는 바다의 용 마렌시아의 노래가 부른 것들 — 셀레네아의 인어 무녀, 몸을 얻은 노래와 물, 바다의 짐승. 물 밖에서는 느리지만, 아군을 치유하고 상대의 강화를 씻어낸다.": "永不遗忘的海之龙玛伦西亚之歌所召唤之物 — 塞勒涅亚的人鱼巫女、化身的歌与水、海洋之兽。离水时迟缓,但能治愈友方并洗去敌方的强化。",
"장착하는 순간 내 생명이 {0} 늘어난다.": "装备瞬间,我方生命增加{0}。",
"장착하면 {0}, 그 뒤": "装备后{0},之后",
"장착하면 {0}이 됨(유닛 카드의 값 · 코인과 상관없이).": "装备后变为{0}(不受单位卡数值・硬币影响)。",
"장착하면 그 스탯이 N이 됨(유닛 카드의 값 · 코인과 상관없이).": "装备后该数值变为N(不受单位卡数值・硬币影响)。",
"장착한 유닛의 공·방·체가 {0}{1} 됨(코인 없음).": "装备单位的攻・防・体变为{0}{1}(无硬币)。",
"장착한 유닛의 공·방·체가 {0}/{1}/{2}{3} 된다": "装备单位的攻・防・体变为{0}/{1}/{2}{3}",
"장착한 유닛의 공·방·체가 적힌 값이 된다. 유닛 코인은 던지지 않는다.": "装备单位的攻・防・体变为所写数值。不投掷单位硬币。",
"장착할 때": "装备时",
"장착할 때 내 생명 +{0}.": "装备时我方生命+{0}。",
