"전장에 있으면 내 마법 피해 +{0}(물리 — 방어부터 깎음).": "在战场上时我方法术伤害+{0}(物理 — 先削防御)。",
"전장에서 맞붙음이 하나 시작될 때마다(이 유닛이 맞붙지 않아도) 받은 피해를 {0} 채우고(원래 체력까지), 이번 턴 깎인 방어를 {0} 되돌린다(카드의 방어까지). 화상이나 불씨가 붙어 있으면 재생하지 않는다. 마법으로 체력이 깎이면 그 마법 바로 다음 맞붙음에는 재생하지 않는다.": "战场上每开始一次交锋(即使此单位未参与),回复{0}点所受伤害(至原本体力为止),并恢复{0}点本回合被削减的防御(至卡牌防御为止)。带有灼烧或余烬时不会再生。若被法术削减体力,则该法术之后紧接的那次交锋不再生。",
"전투 시 상대 코인 개수만큼 추가 데미지.": "战斗时追加等同于对方硬币数的伤害。",
"전투 시작 때 가장 다친 아군 체력 +2.": "战斗开始时,伤势最重的友方体力+2。",
"전투 시작 때 상대가 이번 턴 새로 놓은 유닛마다 체력 −3.": "战斗开始时,敌方本回合每新放置一个单位,其体力−3。",
"전투 시작 때 이 유닛의 화상 · 불씨 · 낙인 · 저주를 지움.": "战斗开始时清除此单位的灼烧・余烬・烙印・诅咒。",
"전투가 시작될 때 내가 공격하는 턴(밀물)이면 공격 +{0}, 방어하는 턴(썰물)이면 방어 +{0}(이번 턴).": "战斗开始时,若为我方攻击回合(涨潮)则攻击+{0},若为防御回合(退潮)则防御+{0}(本回合)。",
"전투가 시작될 때 내가 공격하는 턴(밀물)이면 공격 +{0}, 방어하는 턴(썰물)이면 방어 +{0}(이번 턴). 마법이 바로 거는 물때는 그 자리에서 붙는다.": "战斗开始时,若为我方攻击回合(涨潮)则攻击+{0},若为防御回合(退潮)则防御+{0}(本回合)。法术直接施加的潮汐当即生效。",
"전투가 시작될 때 받은 피해가 가장 큰 아군 유닛 하나(자기 포함)의 체력을 2 채운다.": "战斗开始时,为所受伤害最多的一个友方单位(含自身)回复2点体力。",
"전투가 시작될 때, 이번 턴 상대 전장에 새로 놓인(낸 · 소환된) 유닛마다 체력이 3 깎인다(방어 무시).": "战斗开始时,本回合新进入敌方战场(打出・召唤)的每个单位体力削减3(无视防御)。",
"전투가 시작될 때(화상 · 불씨가 타기 전) 이 유닛의 화상 · 불씨 · 계약의 낙인과 [저주](공포 · 역병)를 지운다.": "战斗开始时(灼烧・余烬燃烧前),清除此单位的灼烧・余烬・契约烙印与[诅咒](恐惧・瘟疫)。",
"준비 단계부터 걸리고, 전투가 시작된 뒤 받은 오라는 이 유닛이 쓰러져도 그 턴이 끝날 때까지 남는다(받은 유닛에 ◎ 칩).": "从准备阶段起生效,战斗开始后获得的光环即使此单位倒下也保留至该回合结束(获得的单位显示◎标记)。",
"천족 깃발이면 판 처음부터 모이는 힘(최대 37): 아군이 [보호막] · [가호]로 막은 피해, 전투가 시작될 때 아군 [정화] 유닛 하나마다 1, [정화]로 씻은 것 하나마다 1, 턴마다 깎인 생명의 절반. [새벽의 해방]으로 한 번에 풀어 공격이 가장 높은 상대부터 체력을 깎는다.": "天族旗帜下自对局开始累积的力量(最多37): 友方以[护盾]・[庇佑]挡下的伤害、战斗开始时每个友方[净化]单位计1、[净化]每洗去一项计1、每回合损失生命的一半。以[黎明解放]一举释放,从攻击最高的敌方开始削减体力。",
"코인 {0}개 — 마법을 쓸 때 던져서 앞면이 나올 때마다 {1}{2}": "硬币{0}枚 — 使用法术时投掷,每出现一次正面{1}{2}",
"코인 {0}개를 던져 앞면마다 {1} {2}{3}": "投掷{0}枚硬币,每个正面{1} {2}{3}",
"타고난 능력": "天生能力",
"턴마다 전투 시작 때 한 번 — 코인 앞면이면 첫 피해를 절반으로.": "每回合战斗开始时一次 — 硬币正面则首次伤害减半。",
"턴마다 전투가 시작될 때 한 번(첫 마법 · 공격보다 먼저) 코인을 던져 앞면이면, 그 턴 처음 받는 피해 한 번(체력 깎임 포함)을 절반(올림)만큼 막는다.": "每回合战斗开始时一次(先于首个法术・攻击)投掷硬币,若为正面,则抵挡该回合首次受到伤害(含体力减少)的一半(向上取整)。",
"판이 길어질수록 숲은 자란다": "对局越长,森林越茂盛",
"포르탄의 고블린 포대장": "福尔坦的哥布林炮台长",
"피해를 준 상대는 이번 턴 방어 −2.": "受其伤害的敌方本回合防御−2。",
"하나가 코인 하나입니다. 마법을 쓸 때 던져서 앞면이 나올 때마다 그 값을 더합니다.{0}": "每个代表一枚硬币。使用法术时投掷,每出现一次正面就加上该数值。{0}",
"화상 붙은 상대와 맞붙으면 피해 + 화상.": "与带灼烧的敌方交锋: 伤害+灼烧值。",
"화상이 붙은 상대 유닛과 맞붙으면(공격 · 반격) 피해가 그 화상 수치만큼 늘어난다.": "与带灼烧的敌方单位交锋时(攻击・反击),伤害增加等同于该灼烧数值。",
"활을 든 유닛: 활 아이템을 장착했거나, 활을 든 사수(바늘탑 견습 사수 · 담비 저격수 …)이거나, [궁사회 무기고]로 활을 받은 유닛(쓰러질 때까지). [별빛 연사]가 그 수만큼 쏜다.": "持弓单位: 装备弓类道具、持弓的射手(针塔见习射手・貂狙击手 …),或通过[弓士会武库]获得弓的单位(直至倒下)。[星光连射]按该数量射击。",
