"(− 코인은": "(− 硬币则为",
"(결정화) ·": "(结晶化) ·",
"(끌어다 놓아도 됩니다).": "(也可以拖放)。",
"(끌어다 놓아도 됩니다). 결정이 되어": "(也可以拖放)。它会化为结晶，",
"(남은 에테르 {0} · 한 번)": "(剩余以太{0} · 一次)",
