"(코인 뒷면 · 운명은 아직 던지지 않은 코인에만). 유닛의 공격·방어·체력 코인은 순번이 같으면 동전 하나라 함께 앞·뒷면이 됩니다(공격 2개·방어 1개면 동전 2개). 장착한 아이템의 코인도 함께 세고, 동전은 최대 5개입니다. 내 코인은 내가": "(硬币反面 · 命运仅对尚未投掷的硬币有效)。单位的攻击 · 防御 · 体力硬币若顺序相同则为同一枚币，一起出正 · 反面(攻击2个 · 防御1个则为2枚币)。装备道具的硬币也一并计算，币最多5枚。自己的硬币由自己通过",
