"결속한 아군이 쓰러지면 가진 피가 모두 바로 뒤 아군에게 옮겨 간다. 남의 피를 머금고 전투에서 살아남으면 다음 턴 준비 때 그 피 주인들이 쓰러질 때의 공격만큼 공격이 오른다(그 턴만).": "结盟的友方倒下时，其所有血液转移给正后方的友方。蕴含他人之血并在战斗中存活的单位，下回合准备时攻击提升，数值等于那些血液主人倒下时的攻击(仅限该回合)。",
