"으로 보내기": "送入",
"으로, 상대 코인은 상대가 세웁니다(5초가 지나면 저절로 멈춤). 양쪽이 멈추면 나온 대로 스탯이 바뀐 뒤 공격 → 반격이 이어집니다. 피해 = 공격 − 방어(최소 0). 쓰러진 유닛과 쓴 마법은 그 자리에서 부서지고 남은 카드는 바로 왼쪽으로 당겨집니다. 피해는 그 턴 안에서만 쌓이고, 턴이 끝나면 회복됩니다.": "停下，对手的硬币由对手停下（5秒后自动停止）。双方都停下后，按结果改变数值，随后进行攻击 → 反击。伤害 = 攻击 − 防御（最少0）。倒下的单位和用过的法术当场破碎，剩余卡牌立即向左靠拢。伤害只在该回合内累积，回合结束即恢复。",
"은 감소 효과를,": "不受减少效果，",
"은 증가 효과를 받지 않습니다(증가·감소 효과 = 마법·특수능력·코인·저주로 스탯이 오르내리는 것). 셋 다 받은 피해는 그대로 쌓이므로 체력만큼 피해를 입으면 쓰러집니다. 코인 때문에 체력이 0 이하가 되면 그 유닛은 쓰러져 소각 더미로 갑니다.": "不受增加效果（增减效果 = 因法术・特殊能力・硬币・诅咒导致数值升降）。三者受到的伤害照样累积，伤害达到体力即倒下。若因硬币使体力降到0以下，该单位倒下并进入焚烧堆。",
"은 증가·감소 효과를 모두,": "不受任何增减效果，",
"을": "",
"을 내고 그 코인만 다시 던집니다. 맞붙을 때마다 한 번(이미 정해진 방어 코인은 다시 던질 수 없음). 준비 단계에서 남겨 둔 에테르를 여기에 씁니다 (남은 에테르는 다음 턴으로 넘어가지 않습니다).": "即可重掷该硬币。每次交锋一次（已确定的防御硬币不能重掷）。准备阶段留下的以太在此使用（剩余以太不会留到下回合）。",
