"— 살아남으면 다음 턴부터 매 턴 그만큼 에테르가 빠진다. 유지비는 레벨 − 1까지(금빛 아이콘이 적어도 하나).": "— 存活的话，从下回合起每回合扣除相应以太。维持费最多为等级 − 1（至少一个金色图标）。",
"— 에테르 1로 그 코인만 다시 던진다 (− 코인은 앞면을 누른다)": "— 用1以太只重掷该硬币（−硬币点正面）",
"— 카드를 사도 줄지 않습니다.": "— 买卡也不会减少。",
"— 하루에 한 번 열리는 길에서 여덟 관문과 망각의 숲을 지납니다.": "— 每天开放一次的道路，穿过八道关卡与遗忘之森。",
", 그 아래 금빛 막대가 경험치. 이름 옆은 전적과 승률.": "，下方金色条为经验值。名字旁是战绩与胜率。",
