": 공격 마법은 공격 턴, 방어 마법은 방어 턴에만 냅니다. 한쪽에 치우치지 않게.": "：攻击法术只在攻击回合、防御法术只在防御回合打出。注意均衡。",
": 공격하는 쪽이 먼저 놓고 준비 완료, 방어하는 쪽은 그 배치를 보고 놓습니다. 마법은 뒷면이라 상대에게 보이지 않습니다.": "：攻击方先放置并准备完毕，防御方看过布阵后再放置。法术为盖放，对手看不到。",
": 받은 피해가 낫고, 다음 턴에는 공격과 방어가 바뀝니다. 공격 턴과 방어 턴이 한 번씩 지나면": "：所受伤害恢复，下回合攻防互换。攻击回合与防御回合各过一次即为",
": 빈 아이콘이 많은 큰 유닛은 강하지만 매 턴 에테르를 먹습니다. 두세 장이면 충분합니다.": "：空图标多的大单位很强，但每回合消耗以太。两三张就够了。",
": 에테르는 결정이 쌓이며 천천히 늘어납니다. 낮은 레벨(1~3) 카드가 넉넉해야 초반에 칸을 채울 수 있습니다.": "：以太随结晶累积缓慢增加。低等级（1~3）卡牌要充足，才能在前期填满格子。",
": 저절로 진행됩니다. 코인을 세우고, 손해 본 코인(뒷면 + 코인 · 앞면 − 코인)을 뒤집을지 고르는 것만 합니다.": "：自动进行。你只需停下硬币，并选择是否翻转吃亏的硬币（反面的+硬币 · 正面的−硬币）。",
": 증가 · 감소 효과를 모두 받지 않습니다(그 스탯의 코인은 던지지 않음).": "：不受任何增减效果（该数值的硬币不投掷）。",
": 증가 효과를 받지 않습니다. 증가 · 감소 효과는 마법 · 특수능력 · 코인 · 저주로 스탯이 오르내리는 것입니다. 기준은 카드에 적힌 값(아이템이 더한 값 포함)이고, 받은 피해는 셋 다 그대로 쌓입니다. 체력에는 고정이 없습니다.": "：不受增加效果。增减效果指因法术 · 特殊能力 · 硬币 · 诅咒导致数值升降。基准为卡牌上的数值（含道具加成），三者受到的伤害照样累积。体力没有固定。",
": 턴이 시작되면 두 사람 모두 핸드를 {0}장까지 뽑고,": "：回合开始时双方都将手牌抽至{0}张，",
": 핸드 카드는 결정이 됩니다. 쓰기 애매한 카드도 결정으로 바뀌어 에테르가 됩니다.": "：手牌可化为结晶。不好用的卡也能变成结晶，转化为以太。",
