". 마법은 효과. [능력]에 마우스를 올리면 뜻.": "。法术为效果。鼠标悬停[能力]可查看含义。",
". 모래시계가 남은 시간을 세고(카드를 뽑는 동안은 멈춤), 0이 되면 준비 완료처럼 턴이 넘어갑니다 — 에테르가 모자라도 묻지 않고 마칩니다. (관리자는 설정에서 끌 수 있습니다)": "。沙漏计算剩余时间（抽牌期间暂停），归0时如同准备完毕一样转移回合 — 即使以太不足也不询问直接结束。（管理员可在设置中关闭）",
". 어두운 결정은 다음 턴이 되면 다시 밝아집니다. 쓰지 않고 남긴 에테르는 다음 턴으로 넘어가지 않습니다.": "。暗淡的结晶到下回合会重新亮起。未用完的以太不会留到下回合。",
". 이제 {0} 카드를 낼 수 있습니다. 바친 카드는 소각장으로 가지만 결정은 판 끝까지 남아": "。现在可以打出{0}卡牌了。献出的卡牌进入焚烧场，但结晶会保留到对局结束",
