"(0 아래로는 내려가지 않음). 체력이 0이 되면 쓰러져 부서지고, 남은 카드는 왼쪽으로 당겨집니다.": "（不会低于0）。体力为0时倒下并破碎，剩余卡牌向左靠拢。",
