"켜면 방 목록에 내 깃발이 보이고, 방 안에서 서로의 깃발 · 덱 점수가 보입니다. 끄면 대전이 시작될 때까지 서로 가려집니다.": "开启后，房间列表会显示你的旗帜，房间内双方可看到彼此的旗帜 · 卡组分数。关闭后，在对战开始前彼此隐藏。",
"{0} 카드 1장": "{0}卡牌1张",
"{0}걸음": "{0}步",
"{0}레벨": "{0}级",
"{pil.resetDay} 0시에 새 주가 시작됩니다. 첫 승을 한 날마다 한 걸음.": "{pil.resetDay}0点开始新的一周。每天首胜前进一步。",
