"**{pil.first} 조각**을 받거나, 그 조각을 걸고 **카드 한 장**(꽝 없음)을 뽑습니다.": "领取**{pil.first}碎片**，或以此为注抽取**一张卡牌**（无空奖）。",
"**{rules.copies}장**까지. 한 장만 되는 등급은 [[rb:cards|등급표]].": "最多**{rules.copies}张**。限一张的品级见[[rb:cards|品级表]]。",
"**강화** 등급은 합성으로만 얻습니다 — [[rb:upgrade|합성소]].": "**强化**品级只能通过合成获得 — [[rb:upgrade|合成所]]。",
"**유니크**는 한 덱에 {deck.uniqueKinds}종까지 넣을 수 있습니다.": "每副卡组最多放入{deck.uniqueKinds}种**独特**卡牌。",
"ETHERION 룰북": "ETHERION 规则书",
"가지고 있던 레거시 카드는 상점 값만큼 조각으로 돌려받습니다.": "拥有的旧版卡牌按商店价格返还为碎片。",
"강화 — {up.from} {up.cost}장 → 강화 카드": "强化 — {up.from}{up.cost}张 → 强化卡牌",
"강화판이 있는 카드만 ({up.kinds}종).": "仅限有强化版的卡牌（{up.kinds}种）。",
"같은 {fuse.from} 카드 **{fuse.cost}장**. 재료는 사라집니다.": "同一{fuse.from}卡牌**{fuse.cost}张**。材料将消耗。",
"같은 {up.from} 유닛 **{up.cost}장**. 재료는 사라집니다.": "同一{up.from}单位**{up.cost}张**。材料将消耗。",
"같은 상대와는 하루 {0}판까지 보상": "与同一对手每天最多{0}局有奖励",
"같은 상자 밑에서 튀어나오는 서랍. {arcade.crystalTurns}라운드 이어서 물을 주면 {arcade.crystal} 조각. 한 번 거르면 처음부터.": "从同一个盒子下方弹出的抽屉。连续{arcade.crystalTurns}回合浇水可得{arcade.crystal}碎片。漏一次就从头开始。",
"같은 카드를 모아 더 좋은 카드로": "集齐相同卡牌，合成更好的卡牌",
"거래로 오간 조각은 경험치가 되지 않습니다.": "交易往来的碎片不计入经验值。",
"게임에서 빠진 카드": "已移出游戏的卡牌",
"게임의 짜임을 섹션별로 모았습니다. 제목을 누르면 펼쳐집니다. 숫자는 지금 게임의 값을 그대로 읽어 옵니다.": "按章节整理了游戏的结构。点击标题即可展开。数值直接读取当前游戏的设定。",
"결과": "结果",
"결정 키우기": "培育结晶",
"경매": "拍卖",
