"계정 — 등록 · 필멸자": "账号 — 注册 · 凡人",
"관문을 이길 때마다 {pil.sealWin}개, 숲을 지나면(하루 한 번) {pil.sealDone}개 더. [[rb:upgrade|강화]]에 씁니다.": "每赢一个关卡得{pil.sealWin}个，穿过森林（每天一次）再得{pil.sealDone}个。用于[[rb:upgrade|强化]]。",
"관문을 처음 지나면 그 깃발의 소문이 순례기에 남습니다.": "首次通过关卡时，该旗帜的传闻会记入巡礼记。",
"교환 제안": "交换提议",
"그 밖": "其他",
"그 카드의 강화판 한 장 — 레벨이 하나 오르고 스탯이 크게 오릅니다. 등급 **{up.grade}**, 어떤 아이템이든 장착.": "该卡牌的强化版一张 — 等级提升一级，属性大幅提升。品级**{up.grade}**，可装备任意道具。",
"그날 첫 승": "当日首胜",
"금요일": "星期五",
"깃발 문양 셋": "三个旗帜纹样",
"꽝": "空奖",
"나오는 정도": "出现率",
"내놓을 것과 원하는 것을 올리고 기한({trade.durations})을 정합니다. 한쪽에 카드 {trade.maxCards}장까지.": "上架你提供的和想要的物品，并设定期限（{trade.durations}）。每方最多{trade.maxCards}张卡牌。",
"다음 입찰은 최고가 + {trade.step}(최소 {trade.stepMin} 조각). 밀린 입찰은 바로 돌려받습니다.": "下次出价为最高价＋{trade.step}（至少{trade.stepMin}碎片）。被超过的出价会立即退还。",
"대기실. 컴퓨터와 대전 · 순례를 한 판 마칠 때마다 표 한 장.": "大厅。每完成一局电脑对战或巡礼得一张券。",
"대상": "对象",
"대전": "对战",
"대전 방식과 보상": "对战模式与奖励",
"대전 중 전장 옆 작은 게임 상자의 릴 셋. 라운드마다 한 번.": "对战中战场旁小游戏盒里的三个转轴。每回合一次。",
"대전은 덱 **{rules.deck}장**으로 합니다. 유닛을 전장 **{rules.slots}칸**에 세우고 마법 · 아이템으로 거들어, 상대 생명 **{rules.life}**을 먼저 다 깎으면 이깁니다.": "对战使用**{rules.deck}张**卡组。将单位部署在战场的**{rules.slots}格**中，以法术 · 道具辅助，率先削光对手**{rules.life}**点生命即获胜。",
"더 받는 것": "额外奖励",
"덱 보호": "卡组保护",
"덱 조정실에서 저장해야 대전 · 순례에 나갑니다.": "须在卡组编辑室保存后才能用于对战 · 巡礼。",
"덱에": "卡组中",
"덱에 있던 자리는 같은 깃발 · 같은 종류의 가진 카드로 채워집니다.": "卡组中的空位将以同旗帜 · 同类型的已有卡牌填补。",
"덱을 짜는 규칙과 덱 보호": "组卡规则与卡组保护",
"덱을 짜는 요령은 [[mn:deck|매뉴얼 '덱 만들기']].": "组卡技巧见[[mn:deck|手册“组建卡组”]]。",
