"이름에는 글자 · 숫자 · 띄어쓰기와 _ - · . 만 쓸 수 있습니다.": "名字只能使用文字 · 数字 · 空格以及 _ - · .",
"이메일 또는 암호가 맞지 않습니다. 암호를 정하지 않았다면 '메일 코드로 로그인'을 눌러 주세요.": "邮箱或密码错误。若未设置密码，请点击“邮件验证码登录”。",
