"화약통을 놓을 빈 칸이 없음": "没有可放置火药桶的空位",
"확인 코드를 메일로 보냈습님(10분).": "验证码已发送至邮箱(10分钟)。",
"환각에 빠뜨릴 상대 유닛이 없음": "没有可施加幻觉的敌方单位",
"환불할 수 없는 주문입님.": "该订单无法退款。",
"환석 {0}을 남겨 두었습님. 오늘 안에 언제든 고를 수 있고, 고르지 않으면 자정에 조각으로 들어옵님.": "已保留幻石{0}。今天内随时可选，若不选，午夜时以碎片形式发放。",
"환석 {0}을 받았습님.": "已领取幻石{0}。",
